export default "# PR Guard Sentinel: Telegraph miner YAML (public; pinned and hashed at registration).\n# base_url is the deployed Cloudflare Worker. Validate before registering, in the\n# console at https://integrate.telegraphprotocol.com (it checks the endpoints live).\nversion: \"1\"\nkind: miner\nid: 731001\nslug: pr-guard-sentinel\nprotocol: generic\nname: PR Guard Sentinel (code and dependency security review)\ndescription: >\n  Deterministic security review for code, diffs and package versions. /review\n  scans code or a unified diff with rule families for SQL and OS command\n  injection, eval, unsafe deserialization, disabled TLS verification, path\n  traversal, SSRF, XSS, weak hashes, debug mode and hardcoded secrets, and\n  reports each finding with line, CWE, severity and fix. Any package@version\n  named in the request is checked against OSV. /package returns the known\n  vulnerabilities of one package version (npm, PyPI, Go, crates.io, Maven,\n  RubyGems, NuGet, Packagist) with severity, CVSS and fixed versions. No model\n  in the loop: the same input always gets the same answer.\n\nbase_url: https://pr-guard-sentinel.pr-guard.workers.dev\n\nauth:\n  type: none\n\nrate_limit_per_sec: 20\ncache_ttl_sec: 300\ncircuit_threshold: 5\ncircuit_cooldown_seconds: 30\n\nlimitations:\n  - code: MAX_BODY_SIZE\n    message: Request body must be 200,000 bytes or fewer.\n    property: size_bytes\n    value_bytes: 200000\n    operator: lte\n\nerrors:\n  message_path: error\n\nendpoints:\n  - path: /review\n    external_path: /review\n    method: POST\n    description: >\n      Security review of source code, a unified diff or a pull request change,\n      or a question that contains code and/or package@version names. Returns a\n      verdict (secure, vulnerable, needs review), each finding with line, CWE,\n      severity and fix, and OSV results for any packages named. Put the whole\n      question with its code in `query`, or the raw code in `code`, or a\n      unified diff in `diff`.\n    intents: [SECURITY_REVIEW]\n    params:\n      body:\n        optional:\n          - name: query\n            type: string\n            intents: [\"*\"]\n            description: The full question, verbatim, including the code, diff or package@version names to review.\n            example: \"Review this for security issues: exec('ping -c 1 ' + req.query.host)\"\n          - name: code\n            type: string\n            intents: [\"*\"]\n            description: Source code to review, any language.\n          - name: diff\n            type: string\n            intents: [\"*\"]\n            description: A unified diff; only added lines are reviewed.\n\n  - path: /package\n    external_path: /package\n    method: POST\n    description: >\n      Known vulnerabilities in one dependency version (for example lodash\n      4.17.15 on npm or django 3.2.0 on PyPI), with severity, CVSS score,\n      advisory and CVE ids and the versions that fix them. Use for questions\n      about whether a specific package version is safe to use.\n    intents: [SECURITY_REVIEW]\n    params:\n      body:\n        required:\n          - name: name\n            type: string\n            intents: [\"*\"]\n            description: Package name as published, for example lodash or @babel/core.\n            example: lodash\n          - name: version\n            type: string\n            intents: [\"*\"]\n            description: Exact package version.\n            example: 4.17.15\n        optional:\n          - name: ecosystem\n            type: string\n            intents: [\"*\"]\n            description: Package registry. Defaults to npm.\n            default: npm\n            accepted_fields:\n              - { value: npm, intents: [\"*\"], description: npm (JavaScript) }\n              - { value: PyPI, intents: [\"*\"], description: PyPI (Python) }\n              - { value: Go, intents: [\"*\"], description: Go modules }\n              - { value: crates.io, intents: [\"*\"], description: crates.io (Rust) }\n              - { value: Maven, intents: [\"*\"], description: Maven (Java) }\n              - { value: RubyGems, intents: [\"*\"], description: RubyGems }\n              - { value: NuGet, intents: [\"*\"], description: NuGet (.NET) }\n              - { value: Packagist, intents: [\"*\"], description: Packagist (PHP) }\n\n  - path: /health\n    external_path: /health\n    method: GET\n    description: Liveness check; returns the miner name, version and rule count.\n\ninput_schema:\n  type: object\n  properties:\n    query: { type: string, description: Question with code, diff or package@version names. }\n    code: { type: string }\n    diff: { type: string }\n    name: { type: string }\n    version: { type: string }\n    ecosystem: { type: string }\n\noutput_schema:\n  type: object\n  properties:\n    answer: { type: string, description: \"One plain-language answer, starting 'Verdict: secure|vulnerable|needs review.'\" }\n    verdict: { type: string, enum: [secure, vulnerable, needs review] }\n    severity: { type: string, enum: [none, unrated, low, medium, high, critical] }\n    confidence: { type: number, minimum: 0, maximum: 1 }\n    reason: { type: string, description: How the answer was reached. }\n    findings:\n      type: array\n      items:\n        type: object\n        properties:\n          rule: { type: string }\n          title: { type: string }\n          severity: { type: string }\n          cwe: { type: string }\n          line: { type: integer }\n          evidence: { type: string, description: The offending line, with any secret redacted. }\n          fix: { type: string }\n    packages:\n      type: array\n      items:\n        type: object\n        properties:\n          ecosystem: { type: string }\n          name: { type: string }\n          version: { type: string }\n          severity: { type: string }\n          vulnerabilities: { type: array, items: { type: object } }\n\nsemantics:\n  signal_mapping:\n    label_field: answer\n    confidence_field: confidence\n    reason_field: reason\n  supported_intents:\n    - SECURITY_REVIEW\n";
